1	/**
2	 * Конфигурация биллинга.
3	 *
4	 * Всё, что меняется между площадками, живёт здесь, а не размазано по коду. Читается через
5	 * resolveConfig: прямое обращение к DEFAULT_CONFIG из модулей запрещено — иначе переопределение
6	 * конфига молча перестаёт действовать на половину мест.
7	 */
8	
9	export interface BillingConfig {
10	  /** Валюта счетов. Других у нас нет, но поле есть: отчётность её читает. */
11	  currency: 'RUB';
12	}
13	
14	export const DEFAULT_CONFIG: BillingConfig = {
15	  currency: 'RUB',
16	};
17	
18	/** Конфиг с переопределениями площадки. Не указанное — из DEFAULT_CONFIG. */
19	export function resolveConfig(partial?: Partial<BillingConfig>): BillingConfig {
20	  return { ...DEFAULT_CONFIG, ...partial };
21	}
